//! Fixture loading shared by the DWARF decode benches.

#![allow(dead_code, reason = "each bench uses a subset of the loaders")]

use edr_solidity::artifacts::{CompilerInput, CompilerOutput, SolxBytecode};

/// The committed solx stack-trace scenarios fixture, regenerated by
/// `edr_tool_cli`'s `gen-solx-fixtures` (see `fixtures/README.md`).
pub fn stack_trace_scenarios() -> (CompilerInput, CompilerOutput<SolxBytecode>) {
    load(
        include_str!("../../fixtures/solx_compiler_input_stack_trace_scenarios.json"),
        include_str!("../../fixtures/solx_compiler_output_stack_trace_scenarios.json"),
    )
}

/// The same scenarios compiled by the slang compiler, regenerated by
/// `edr_tool_cli`'s `gen-slang-fixtures`.
pub fn slang_stack_trace_scenarios() -> (CompilerInput, CompilerOutput<SolxBytecode>) {
    load(
        include_str!("../../fixtures/slang_compiler_input_stack_trace_scenarios.json"),
        include_str!("../../fixtures/slang_compiler_output_stack_trace_scenarios.json"),
    )
}

/// The committed input carries empty source bodies, so the live sources are
/// spliced back in, as `debug_info::dwarf`'s tests do.
fn load(input: &str, output: &str) -> (CompilerInput, CompilerOutput<SolxBytecode>) {
    let mut input: CompilerInput =
        serde_json::from_str(input).expect("the committed fixture input must parse");
    input
        .sources
        .get_mut("project/contracts/StackTraceScenarios.sol")
        .expect("input must contain StackTraceScenarios.sol")
        .content = include_str!("../../fixtures/sources/StackTraceScenarios.sol").to_string();
    input
        .sources
        .get_mut("project/contracts/StackTraceScenariosBase.sol")
        .expect("input must contain StackTraceScenariosBase.sol")
        .content = include_str!("../../fixtures/sources/StackTraceScenariosBase.sol").to_string();
    assert!(
        input
            .sources
            .values()
            .all(|source| !source.content.is_empty()),
        "the committed input has empty source bodies; every source must be spliced back in above"
    );

    let output: CompilerOutput<SolxBytecode> =
        serde_json::from_str(output).expect("the committed fixture output must parse");

    (input, output)
}
